import unittest,re
from tools.kjv_archive import load_register,read
class RevelationBeastHarvestTests(unittest.TestCase):
 def test_beast_counts_and_supplied_readings(self):
  prior,_=load_register('0.10-kjv.274');lang,manifest=load_register('0.10-kjv.275')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('revelation-'):c for c in read(lang.folder/'revelation-beast-and-harvest-cases.json')};self.assertEqual(len(cases),46)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}-{'worship'}&set(r['keys']))
  anchors={'13:1': ['i upon sea sand stand:pa', 'seven head:pl and ten horn:pl', 'his/horn:pl ten crown:pl', 'his/head:pl kjv_blaspheme:ev name'], '13:2': ['like leopard', 'bear_animal foot:pl', 'lion mouth', 'his/power and his/seat and great authority'], '13:3': ['one_num of his/head:pl as to death', 'deadly wound heal:psv:pa'], '13:4': ['kjv_dragon_revelation', 'beast kjv_worship:pa', 'who like beast be:pr:q', 'who with he war make:inf able be:pr:q'], '13:5': ['great thing:pl and kjv_blaspheme:ev:pl', 'forty and two month:pl continue:inf'], '13:6': ['his/name and his/kjv_tabernacle and they who in heaven'], '13:7': ['holy person:pl war', 'overcome:inf', 'all kjv_family:pl and tongue:pl and nation:pl'], '13:8': ['from world kjv_foundation slay:psv:pp kjv_lamb life book', 'write:psv:neg:pr'], '13:9': ['ear have:pr he hear:opt'], '13:10': ['into kjv_captivity lead:pr into kjv_captivity go:fu', 'with sword kill:pr with sword kill:psv:must', 'patience and faith'], '13:11': ['other beast out of earth', 'two horn:du like kjv_lamb', 'as kjv_dragon_revelation speak:pa'], '13:12': ['all first beast power', 'use:pr', 'first beast whose deadly wound'], '13:13': ['great kjv_wonder:pl', 'fire from heaven on earth in man:pl sight'], '13:14': ['miracle:pl', 'image make:should', 'by sword wound have:pa and live:pa'], '13:15': ['to beast image life give:inf', 'both speak:should', 'kill:psv:should'], '13:16': ['both small and great rich and poor free and bound', 'kjv_right_side hand or in their/forehead:pl mark'], '13:17': ['buy:may or sell:may', 'mark or beast name or his/name kjv_number:ev'], '13:18': ['beast kjv_number:ev kjv_number:opt', 'man kjv_number:ev', 'six+hundred and five+twelve and six'], '14:1': ['mountain kjv_sion_revelation', 'twelve+twelve+thousand his/father name'], '14:2': ['as many water:pl voice', 'as great thunder voice', 'harp:ag:pl with their/harp:pl harp:cv'], '14:3': ['as new song', 'four beast:pl', 'except twelve+twelve+thousand'], '14:4': ['with woman:pl defile:psv:neg:pa', 'virgin:pl', 'wherever kjv_lamb', 'to god and to kjv_lamb kjv_firstfruits'], '14:5': ['no kjv_guile', 'before god throne without fault'], '14:6': ['eternal kjv_gospel', 'every nation and kjv_family and tongue and people proclaim:inf'], '14:7': ['his/judge:ev hour', 'heaven and earth and sea and water:pl kjv_fountain:pl'], '14:8': ['kjv_babylon_revelation fall:perf fall:perf', 'that great city', 'her/kjv_fornication wrath wine'], '14:9': ['third angel', 'beast and his/image', 'his/forehead or in his/hand'], '14:10': ['without mix:ev', 'his/indignation cup', 'holy angel:pl presence and in kjv_lamb presence', 'fire and kjv_brimstone'], '14:11': ['forever and forever', 'day nor night no rest', 'his/name mark'], '14:12': ['god command:pl and kjv_jesus_matthew faith'], '14:13': ['from now in lord die:pr', 'yes spirit say:pr', 'rest:may and their/work:pl they:a follow:pr'], '14:14': ['white cloud', 'one_num like man son', 'gold:adj crown', 'sharp kjv_sickle'], '14:15': ['thy/kjv_sickle in thrust:imp and reap:imp', 'for thee reap:inf time', 'harvest ripe'], '14:16': ['his/kjv_sickle on earth', 'earth reap:psv:pa'], '14:17': ['other angel', 'he also sharp kjv_sickle'], '14:18': ['out of altar', 'over fire power', 'kjv_grape_cluster:pl', 'her/grape:pl fully ripe'], '14:19': ['earth kjv_vine', 'god wrath great kjv_winepress'], '14:20': ['outside city', 'blood', 'horse bridle:pl', 'thousand and six+hundred kjv_furlong_source:pl'], '15:1': ['seven angel:pl seven last plague:pl', 'god wrath up fill:psv:pr'], '15:2': ['as glass sea with fire', 'over beast and over his/image and over his/mark and over his/name kjv_number:ev', 'god harp:pl'], '15:3': ['kjv_moses song and kjv_lamb song', 'kjv_righteous and true', 'thou holy person:pl king'], '15:4': ['fear:neg:fu', 'glorify:neg:fu:q', 'thou only holy', 'thy/judge:ev:pl manifest'], '15:5': ['testimony kjv_tabernacle kjv_temple in heaven'], '15:6': ['seven angel:pl', 'seven plague:pl', 'pure and white linen', 'breast:pl with gold:adj kjv_girdle:pl kjv_gird:psv:pp'], '15:7': ['one_num of four beast:pl to seven angel:pl seven gold:adj kjv_vial_wrath_revelation:pl', 'forever and forever live:pr'], '15:8': ['from god glory and from his/power', 'no man', 'seven angel:pl seven plague:pl']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('i upon sea sand stand:pa',cases['13-1']['analysis'])
  self.assertIn('his/horn:pl ten crown:pl',cases['13-1']['analysis'])
  self.assertIn('two horn:du',cases['13-11']['analysis'])
  self.assertIn('six+hundred and five+twelve and six',cases['13-18']['analysis'])
  self.assertIn('twelve+twelve+thousand his/father name',cases['14-1']['analysis'])
  self.assertIn('no kjv_guile',cases['14-5']['analysis'])
  self.assertIn('fall:perf fall:perf',cases['14-8']['analysis'])
  self.assertIn('rest:may and their/work:pl',cases['14-13']['analysis'])
  self.assertIn('over his/mark',cases['15-2']['analysis'])
  self.assertIn('thou holy person:pl king',cases['15-3']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),3)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
